const GENERATORS = Object.freeze([
  0x3b6a57b2n,
  0x26508e6dn,
  0x1ea119fan,
  0x3d4233ddn,
  0x2a1462b3n,
]);

export function polymod(values) {
  let checksum = 1n;

  for (const value of values) {
    const top = checksum >> 25n;
    checksum = ((checksum & 0x1ffffffn) << 5n) ^ value;

    for (let index = 0; index < GENERATORS.length; index += 1) {
      if (((top >> BigInt(index)) & 1n) === 1n) {
        checksum ^= GENERATORS[index];
      }
    }
  }

  return checksum;
}

export function expandHrp(hrp) {
  const expanded = [];

  for (const character of hrp) {
    expanded.push(BigInt(character.codePointAt(0) >> 5));
  }

  expanded.push(0n);

  for (const character of hrp) {
    expanded.push(BigInt(character.codePointAt(0) & 31));
  }

  return expanded;
}

import { expandHrp } from './hrp.mjs';
import { polymod } from './polymod.mjs';

const CHECKSUM_LENGTH = 6;

function normalizeValue(value) {
  if (typeof value === 'bigint') {
    return value;
  }

  if (typeof value === 'number' && Number.isSafeInteger(value)) {
    return BigInt(value);
  }

  throw new TypeError('Bech32 values must be integers');
}

function normalizeValues(values) {
  return values.map(normalizeValue);
}

export function createChecksum(hrp, data) {
  const values = [...expandHrp(hrp), ...normalizeValues(data)];
  const padding = Array.from({ length: CHECKSUM_LENGTH }, () => 0n);
  const remainder = polymod([...values, ...padding]) ^ 1n;
  const checksum = [];

  for (let index = 0; index < CHECKSUM_LENGTH; index += 1) {
    const shift = BigInt(5 * (CHECKSUM_LENGTH - 1 - index));
    checksum.push(Number((remainder >> shift) & 31n));
  }

  return checksum;
}

export function verifyChecksum(hrp, data) {
  const values = [...expandHrp(hrp), ...normalizeValues(data)];
  return polymod(values) === 1n;
}

const DECIMAL_INTEGER_PATTERN = /^[+-]?\d(?:_?\d)*$/;

export class PythonValueError extends Error {
  constructor(value) {
    super(`invalid literal for int() with base 10: '${value}'`);
    this.name = 'ValueError';
    this.value = value;
  }
}

export function parsePythonInt(value) {
  const normalized = value.trim();

  if (!DECIMAL_INTEGER_PATTERN.test(normalized)) {
    throw new PythonValueError(value);
  }

  return BigInt(normalized.replaceAll('_', ''));
}

export function parseCommaSeparatedIntegers(value) {
  return value.split(',').map(parsePythonInt);
}

export function formatPythonList(values) {
  return `[${values.map((value) => String(value)).join(', ')}]`;
}

export function formatPythonBoolean(value) {
  return value ? 'True' : 'False';
}

const OPTIONS = Object.freeze(['--a', '--b', '--help']);
const NEGATIVE_NUMBER_PATTERN = /^-\d+$|^-\d*\.\d+$/;

export class ArgumentParserExit extends Error {
  constructor(code, stream, text) {
    super(text);
    this.name = 'ArgumentParserExit';
    this.code = code;
    this.stream = stream;
    this.text = text;
  }
}

function usage(programName) {
  return `usage: ${programName} [-h] --a A --b B\n`;
}

function helpText(programName) {
  return `${usage(programName)}\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n`;
}

function parserError(programName, message) {
  throw new ArgumentParserExit(
    2,
    'stderr',
    `${usage(programName)}${programName}: error: ${message}\n`,
  );
}

function showHelp(programName) {
  throw new ArgumentParserExit(0, 'stdout', helpText(programName));
}

function isRecognizedOption(token) {
  if (token === '-h') {
    return true;
  }

  const optionName = token.split('=', 1)[0];
  return OPTIONS.includes(optionName)
    || OPTIONS.filter((option) => option.startsWith(optionName)).length === 1;
}

function canBeSeparateValue(token) {
  return token === '-' || !isRecognizedOption(token) && NEGATIVE_NUMBER_PATTERN.test(token);
}

function resolveLongOption(token, programName) {
  const [optionName, explicitValue] = token.includes('=')
    ? [token.slice(0, token.indexOf('=')), token.slice(token.indexOf('=') + 1)]
    : [token, undefined];

  if (OPTIONS.includes(optionName)) {
    return { optionName, explicitValue };
  }

  const matches = OPTIONS.filter((option) => option.startsWith(optionName));
  if (matches.length === 1) {
    return { optionName: matches[0], explicitValue };
  }

  if (matches.length > 1) {
    parserError(
      programName,
      `ambiguous option: ${optionName} could match ${matches.join(', ')}`,
    );
  }

  return null;
}

export function parseCommandLine(argv, programName) {
  const parsed = { a: undefined, b: undefined };
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--') {
      extras.push(...argv.slice(index));
      break;
    }

    if (token === '-h') {
      showHelp(programName);
    }

    if (token.startsWith('--')) {
      const resolved = resolveLongOption(token, programName);

      if (resolved === null) {
        extras.push(token);
        continue;
      }

      const { optionName, explicitValue } = resolved;

      if (optionName === '--help') {
        if (explicitValue !== undefined) {
          parserError(
            programName,
            `argument -h/--help: ignored explicit argument '${explicitValue}'`,
          );
        }
        showHelp(programName);
      }

      let value = explicitValue;
      if (value === undefined) {
        const next = argv[index + 1];
        if (next === undefined || !canBeSeparateValue(next) && next.startsWith('-')) {
          parserError(programName, `argument ${optionName}: expected one argument`);
        }
        value = next;
        index += 1;
      }

      parsed[optionName.slice(2)] = value;
      continue;
    }

    if (token.startsWith('-') && token !== '-' && !NEGATIVE_NUMBER_PATTERN.test(token)) {
      extras.push(token);
      continue;
    }

    extras.push(token);
  }

  const missing = [];
  if (parsed.a === undefined) {
    missing.push('--a');
  }
  if (parsed.b === undefined) {
    missing.push('--b');
  }

  if (missing.length > 0) {
    parserError(
      programName,
      `the following arguments are required: ${missing.join(', ')}`,
    );
  }

  if (extras.length > 0) {
    parserError(programName, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return parsed;
}

import { parseCommandLine, ArgumentParserExit } from './lib/argparse.mjs';
import { createChecksum, verifyChecksum } from './lib/checksum.mjs';
import { parseCommaSeparatedIntegers } from './lib/pythonInt.mjs';
import { formatPythonBoolean, formatPythonList } from './lib/pythonFormat.mjs';

function programName() {
  const scriptPath = process.argv[1] ?? 'test10.mjs';
  return scriptPath.split(/[\\/]/).pop() || 'test10.mjs';
}

function main() {
  const args = parseCommandLine(process.argv.slice(2), programName());
  const data = parseCommaSeparatedIntegers(args.b);
  const checksum = createChecksum(args.a, data);
  const combined = [...data, ...checksum];
  const isValid = verifyChecksum(args.a, combined);

  console.log(formatPythonList(checksum));
  console.log(formatPythonBoolean(isValid));
}

try {
  main();
} catch (error) {
  if (error instanceof ArgumentParserExit) {
    const stream = error.stream === 'stdout' ? process.stdout : process.stderr;
    stream.write(error.text);
    process.exitCode = error.code;
  } else {
    throw error;
  }
}
